"""
Algorithm 1: exact evaluation of the Shtarkov sum of a memoryless class
by the method of types (numerically stable, log-space).
"""

from __future__ import annotations

import math
from typing import Iterator, List, Sequence, Tuple


def compositions(n: int, m: int) -> Iterator[Tuple[int, ...]]:
    """All m-tuples of nonnegative integers summing to n (i.e. all types)."""
    if m == 1:
        yield (n,)
        return
    for first in range(n + 1):
        for rest in compositions(n - first, m - 1):
            yield (first,) + rest


def log_type_weight(counts: Sequence[int], n: int) -> float:
    """Natural log of  (n choose N) * prod_a (N_a/n)^{N_a}, the total contribution
    of one type class to the Shtarkov sum."""
    value = math.lgamma(n + 1)
    for c in counts:
        value -= math.lgamma(c + 1)
        if c > 0:
            value += c * math.log(c / n)
    return value


def shtarkov_sum_iid(n: int, m: int) -> float:
    """Exact Shtarkov sum C_S of the memoryless class on A^n with |A| = m.

    Complexity: O(m * binom(n+m-1, m-1)) arithmetic operations and O(1) memory
    beyond the accumulation buffer; for m = 2 this is O(n).
    """
    if n == 0:
        return 1.0
    terms: List[float] = [log_type_weight(t, n) for t in compositions(n, m)]
    peak = max(terms)
    return math.exp(peak) * sum(math.exp(t - peak) for t in terms)


def price_of_universality_bits(n: int, m: int) -> float:
    """The minimax pointwise redundancy log2 C_S, in bits."""
    return math.log2(shtarkov_sum_iid(n, m))


def proved_bounds(n: int, m: int) -> Tuple[float, float]:
    """(packing lower bound, type upper bound) in bits."""
    return math.log2(m), (m - 1) * math.log2(n + 1)


if __name__ == "__main__":
    for n in (8, 32, 128):
        for m in (2, 3):
            lo, hi = proved_bounds(n, m)
            price = price_of_universality_bits(n, m)
            assert lo <= price <= hi
            print(f"n={n:4d} m={m}:  {lo:.3f} <= {price:.4f} <= {hi:.3f} bits")

"""
Algorithm 2: the normalized maximum likelihood (NML) universal code, implemented
enumeratively via types.  Encoding and decoding of a message over an m-letter
alphabet with the minimax-optimal code for the memoryless class.
"""

from __future__ import annotations

import math
from typing import Iterator, List, Sequence, Tuple


def compositions(n: int, m: int) -> Iterator[Tuple[int, ...]]:
    if m == 1:
        yield (n,)
        return
    for first in range(n + 1):
        for rest in compositions(n - first, m - 1):
            yield (first,) + rest


def multinomial(counts: Sequence[int]) -> int:
    total, value = sum(counts), math.factorial(sum(counts))
    for c in counts:
        value //= math.factorial(c)
    return value


def word_type(word: Sequence[int], m: int) -> Tuple[int, ...]:
    counts = [0] * m
    for letter in word:
        counts[letter] += 1
    return tuple(counts)


def max_likelihood(counts: Sequence[int]) -> float:
    """max_theta p_theta(x) for any word x of the given type."""
    n = sum(counts)
    value = 1.0
    for c in counts:
        if c > 0:
            value *= (c / n) ** c
    return value


def shtarkov_sum(n: int, m: int) -> float:
    return sum(multinomial(t) * max_likelihood(t) for t in compositions(n, m))


def type_index(counts: Tuple[int, ...], n: int, m: int) -> int:
    """Rank of a type in the lexicographic enumeration of all types."""
    return sorted(compositions(n, m)).index(tuple(counts))


def word_index_within_type(word: Sequence[int], m: int) -> int:
    """Combinatorial rank of a word among all words with the same letter counts.

    Standard enumerative ranking: scan left to right, and at each position add the
    number of words that would start with a smaller admissible letter.
    """
    counts = list(word_type(word, m))
    n = len(word)
    rank = 0
    for pos, letter in enumerate(word):
        remaining = n - pos - 1
        for smaller in range(letter):
            if counts[smaller] > 0:
                counts[smaller] -= 1
                rank += multinomial(counts) if remaining >= 0 else 0
                counts[smaller] += 1
        counts[letter] -= 1
    return rank


def nml_code_length_bits(word: Sequence[int], m: int) -> float:
    """The exact NML code length  -log2 maxlik(x) + log2 C_S."""
    n = len(word)
    counts = word_type(word, m)
    return -math.log2(max_likelihood(counts)) + math.log2(shtarkov_sum(n, m))


def encode(word: Sequence[int], m: int) -> Tuple[int, int, float]:
    """Return (type index, index within type, exact NML length in bits).

    The two integers are a lossless representation of the message; the enumerative
    code that writes them costs log2(#types) + log2(multinomial) bits, which is within
    an additive constant of the NML length.
    """
    n = len(word)
    counts = word_type(word, m)
    return type_index(counts, n, m), word_index_within_type(word, m), nml_code_length_bits(word, m)


def decode(t_index: int, w_index: int, n: int, m: int) -> List[int]:
    """Inverse of `encode`: reconstruct the message from its two indices."""
    counts = list(sorted(compositions(n, m))[t_index])
    word: List[int] = []
    for pos in range(n):
        for letter in range(m):
            if counts[letter] == 0:
                continue
            counts[letter] -= 1
            block = multinomial(counts)
            if w_index < block:
                word.append(letter)
                break
            w_index -= block
            counts[letter] += 1
    return word


if __name__ == "__main__":
    m, n = 3, 7
    message = [0, 2, 1, 1, 0, 2, 1]
    t, w, length = encode(message, m)
    assert decode(t, w, n, m) == message
    print(f"message      : {message}")
    print(f"type index   : {t}")
    print(f"word index   : {w}")
    print(f"NML length   : {length:.4f} bits")
    print(f"raw length   : {n * math.log2(m):.4f} bits")
    print(f"round trip   : {decode(t, w, n, m)}")
